526	    }
527	
528	    @Override
529	    @Transactional(readOnly = true)
530	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
531	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
532	    }
533	
534	    private <T> T findEntityById(Supplier<T> supplier) {
535	        try {
536	            return supplier.get();
537	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
538	            // Just ignore not found exceptions for Jdbc/Jpa realization
539	            return null;
540	        }
541	    }
542	
